			body:
				'"Gerrymander" — ᐃᐧᑎᒋᑫᐃᐧᐣ ᓇᒪᐃᐧᔭ ᐋᐸᒋᐦᑖᑲᐧᐤ ᐃᐢᐱ ᑭᒋᔫᐠ ᒪᒪᐃᐧᐦᑲᒪᑎᐃᐧᐣ ᓇᓂᐢᑖᐠ. ᒪᑲ ᑮᐢᐱᐣ ᐊᐦᐃᔭᒻᐱ — ᑖᐱᐢᑯᐣ ᒥᓯᐁᐧ ᐊᐊᐧᔭ ᑲ-ᐯᐦᑕᐦᐠ — ᐅᑎᐢᑫᐃᐧᐣ ᑲᑭ-ᒥᐢᑲᒪᐠ ᑲᐧᔭᐢᑭ ᑲ-ᒋᔥᒋᑌᐧᐃᐧᐣ ᑲᑭ-ᐊᑎᑎᐧᔭᐢᑌᑲᑌᐠ <em>ᐊᑎᐦᑌᑫᐧᐃᐧᐣ ᐅᔑᐦᑖᐃᐧᐣ (minority proposal)</em>, ᑮᐢᐱᐣ ᐋᐸᒋᐦᑖᑲᐧᐤ, ᐊᓂᒪ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᑭᔥᑫᔨᐢᑲᑲᐤ ᑲᐦᑭᔭᐤ ᒨᔭ-ᑲᐧᔭᐢᑭ-ᐃᔑᓇᐦᐃᑫᐃᐧᐣ. ᓀᐅᐧᐠ ᓂᔭᓄᐠ ᑭᔥᑲᒋᔭᓯᓀᐦᐃᑫᐃᐧᓇ ᑲᑭ-ᐱᐢᑭᔥᑲᑫᐠ ᐊᐢᑭ-ᐅᔑᐦᑖᐃᐧᐣ ᐊᔭᒥᐦᐁᐢᑕᒪᑫᐃᐧᐣ ᐃᑎᐱᐢᑲᐧᐢᒋᑲᐧᐤ <em>ᐊᑎᐦᑌᑫᐧᐃᐧᐣ ᐅᔑᐦᑖᐃᐧᐣ</em> ᐁᑲᐧ ᓇᒪᐃᐧᔭ ᐃᑎᐱᐢᑲᐧᐢᒋᑲᐧᐤ <em>ᒥᐦᒋᑌᐃᐧᐣ ᐅᔑᐦᑖᐃᐧᐣ (majority proposal)</em>; ᓂᔮᓀᐡᐠ ᓂᓯᔥᑲᐢᒋᑫᐃᐧᐣ ᓇᐦᐃᔓᐦᑭᐢᑲᒻ ᓂᔣᒃ.',
