			t1_r4_b: '<strong>ᑭᓇᔭᑫᐧᔪᑲᐧᐠ 51.7% (ᓇᒪᐃᐧᔭ 100 ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇᐠ ᐅᑎᐦᐃᑌᐠ ᑭᑲ-ᐅᑎᓂᑕᒻ)</strong>',
			seat_count_note: '2026 ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᒥᑕᑕᑦ ᐯᔭᐠ <strong>89</strong> ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇᐠ ᐊᔮᐤ; ᑲᐧᔭᐢᐠ-ᐃᔑᓇᐦᐃᑫᐃᐧᐣ <strong>87</strong>-ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇᐠ 2019 ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇᐠ ᐋᐸᒋᐦᑖᐤ; Lunty ᒪᒪᐃᐧᐢᑌᐃᐧᐣ ᑭᑲ-ᐅᔑᐦᑖᐤ <strong>91</strong>. ᒥᓯᐁᐧ ᐃᐢᐱᒪᓇᐠ ᑫᐧᐢᑕᐱᐃᐧᓇ <em>ᑲᔥᑭᐦᑖᐃᐧᓇ</em> ᐃᑌᔨᐦᑕᒪᐠ. 2019 ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐃᔑ-ᒪᒋᐊᐧᔅᒋᑫᐃᐧᓇ ReCom ᐋᐸᒋᐦᑕᒻ ᑲᑮᔭᐢ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐋᐸᒋᐦᑖᐤ ᒪᒋᑐᑕᒪᑲᐃᐧᐣ ᐅᐦᒋ.',
			pattern_intro: 'ᒥᐢᑲᒪᑫᐃᐧᓇ — ᓂᔥᑐ ᐱᔥᑭᔥᑌᐃᐧᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐅᐦᒋ — ᐊᔭᒥᔅᑫᐃᐧᓇ ᐊᓂᒪ ᑭᒋ-ᐃᔑᐦᑎᔥᑲᐃᐧᐣ.',
			sub1_h: 'ᓀᐅᐧᐠ ᐊᑎᐢᑎᐦᐃᑫᐃᐧᓇ ᑯᑕᑲᐠ ᑲ-ᑮ-ᐅᔑᐦᑖᑲᐧᐠ',
			sub1_p: 'Elections Alberta ᑲᔅᑭᔥᑌᐃᐧᐣ ᑮᔓᐦᐃᑫᐃᐧᓇ ᐋᐸᒋᐦᑖᑲᐧᐠ ᐃᐢᐱᐦᑌ, ᐊᑎᐦᑌᑫᐧᐃᐧᐣ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᐣ ᐃᐢᐱᐦᑌᔪᑲᐧᐠ ᒥᓯᐁᐧ ᐊᔭᔥᐱᔅᑫᐧᐃᐧᐣ ᓂᓯᔥᑲᐢᒋᑫᐃᐧᐣ ᐃᐢᒋᐦᐃᑲᐧᐠ.',
