			sub2_h: '50/50 tipping point: ᓇᒬᔭ 100 ᐅᐦᒋ 1,010,000 ᑲᐧᔭᐢᐠ ᐊᐢᑭ-ᑮᔓᐦᐃᑫᐃᐧᓇ ᐅᑎᓂᑌᐤ',
