			p4: 'ᐃᐧᑎᒋᑫᐃᐧᓇ ᑲᑯ ᐅᐦᑎᓂᑫᐃᐧᓇ: <a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>'
